import React, {useEffect, useState} from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import {useTranslation} from "react-i18next";

import {
    Button,
    Drawer,
    Icon,
    ListItemButton,
    ListItemIcon,
    ListItemText,
    Stack,
    styled, Typography,
    useMediaQuery
} from "@mui/material";
import Box from "@mui/material/Box";
import {ThemeProvider} from "@mui/material/styles";
import {theme} from "../../../config/ThemeMUI";
import {ContainerSx, MenuDrawerBox} from "./MenuStylex";
import {t} from "i18next";
import ButtonGroup from "@mui/material/ButtonGroup";



function MainMenu({ children }) {
    const menuItems =
        [{name: t('Home'), path: 'home', icon: 'home'},
            {name:t('Income'), path: 'income', icon: 'trending_up'},
            {name:t('Expenses'), path: 'outcome', icon: 'trending_down'},
            {name:t('Tools'), path: 'financial-tools', icon: 'calculate'}]

    const [open, setOpen] = useState(false);
    const drawerWidth = 240
    const isPortrait = useMediaQuery('(orientation: portrait)');

    const [auth] = useState(()=>{
        const savedToken = localStorage.getItem('token');
        return savedToken ? JSON.parse(savedToken) : '';
    })
    const [language] = useState(()=>{
        const savedToken = localStorage.getItem('language');
        return savedToken ? JSON.parse(savedToken) : 'en';
    })

    const navigate = useNavigate();
    const location = useLocation();
    const [selectedButton, setSelectedButton] = useState(location.pathname);

    console.log(selectedButton)
    const handleButtonClick = (path) => {
        setSelectedButton(path);
        navigate(path, { state: { auth: auth, language: language } });
    };


    if (isPortrait){
        return (
            <ThemeProvider theme={theme}>
                <Stack sx={{
                    minHeight: '100vh', // Ensures the container takes up full viewport height
                    display: 'flex',
                    maxWidth:'100vw',
                    overflowX: 'null',

                }}>
                    <Box sx={{ flexGrow: 1 }}>
                        {children}
                    </Box>

                    <Box sx={{
                        bgcolor: 'primary.dark',
                        width: '100%',
                        position: 'sticky',
                        bottom: 0,
                        display: 'flex',
                        justifyContent: 'space-around', // Space buttons evenly
                        alignItems: 'center', // Center buttons vertically
                        padding: '2% 0 2% 0',
                    }}>

                        {menuItems.map(item=>{
                            return(
                                <>
                                    <Button onClick={() => handleButtonClick('/money-manager/' + item.path)}
                                            variant={selectedButton.includes(item.path) ? 'contained' : 'text'}

                                    >
                                        {selectedButton.includes(item.path) ? <Typography color={'primary.light'}>{item.name}</Typography>  : <Icon>{item.icon}</Icon>}


                                    </Button>
                                </>
                            )
                        })}
                        {/*<button*/}

                        {/*    onClick={() => handleButtonClick('/money-manager/home')}*/}
                        {/*>*/}
                        {/*    <Icon>home</Icon>*/}
                        {/*    <br/>*/}
                        {/*    {t("Home")}*/}
                        {/*</button>*/}

                        {/*<button*/}

                        {/*    onClick={() => handleButtonClick('/money-manager/income')}*/}
                        {/*>*/}
                        {/*    <Icon sx={{ color: 'primary.light' }}>trending_up</Icon>*/}
                        {/*    <br/>*/}
                        {/*    {t("Income")}*/}
                        {/*</button>*/}

                        {/*<button*/}

                        {/*    onClick={() => handleButtonClick('/money-manager/outcome')}*/}
                        {/*>*/}
                        {/*    <Icon sx={{ color: 'primary.light' }}>trending_down</Icon>*/}
                        {/*    <br/>*/}
                        {/*    {t("Expenses")}*/}
                        {/*</button>*/}
                        {/*<button*/}
                        {/*    */}
                        {/*    onClick={() => handleButtonClick('/money-manager/financial-tools')}*/}
                        {/*>*/}
                        {/*    <Icon>calculate</Icon>*/}
                        {/*    <br/>*/}
                        {/*    {t("Tools")}*/}
                        {/*</button>*/}
                    </Box>
                </Stack>
            </ThemeProvider>


        )
    }




    const openedMixin = (theme) => ({
        height: 'fit-content',
        [theme.breakpoints.up('sm')]: {
            width: drawerWidth,
            height: '100%',
            transition: theme.transitions.create('width', {
                easing: theme.transitions.easing.sharp,
                duration: theme.transitions.duration.enteringScreen,
            }),
            overflowX: 'hidden',
        },

    });

    const closedMixin = (theme) => ({
        transition: theme.transitions.create('width', {
            easing: theme.transitions.easing.sharp,
            duration: theme.transitions.duration.leavingScreen,
        }),
        overflowX: 'hidden',
        height: 'fit-content',
        width: `100vw`,
        [theme.breakpoints.up('sm')]: {
            width: `calc(${theme.spacing(8)} + 1px)`,
            height: '100%',
        },
    });
    const MyDrawer = styled(Drawer, { shouldForwardProp: (prop) => prop !== 'open' })(
        ({ theme, open }) => ({


            ...(open && {
                ...openedMixin(theme),
                '& .MuiDrawer-paper': openedMixin(theme),
            }),
            ...(!open && {
                ...closedMixin(theme),
                '& .MuiDrawer-paper': closedMixin(theme),
            }),

            display: 'absolute',

            [theme.breakpoints.up('sm')]: {
                width: drawerWidth,
                // flexShrink: 0,
                // whiteSpace: 'nowrap',
                // boxSizing: 'border-box',
                ...(open && {
                    ...openedMixin(theme),
                    '& .MuiDrawer-paper': openedMixin(theme),
                }),
                ...(!open && {
                    ...closedMixin(theme),
                    '& .MuiDrawer-paper': closedMixin(theme),
                }),
            },


        }),
    );


    const handleDrawerClose = () => {
        if (isPortrait){
            setOpen(false)
        } else {
            setOpen(!open);
        }

    };


    return(
        <ThemeProvider theme={theme}>
            <Box sx={ContainerSx}>

                <MyDrawer variant="permanent" open={isPortrait ? false : open }>

                    <Box sx={MenuDrawerBox}>
                        <ListItemButton onClick={handleDrawerClose} sx={{

                            '.MuiListItemText-primary': {
                                color: 'primary.light',
                            },
                            backgroundColor: 'primary.dark', //
                            '&:hover': {
                                backgroundColor: 'primary.main',
                            },
                            '&.Mui-selected': {
                                backgroundColor: 'primary.light',
                                '&:hover': {
                                    backgroundColor: 'primary.dark',
                                },
                            },
                            color: 'primary.light',
                        }}>
                            <ListItemIcon
                                sx={{

                                    [theme.breakpoints.up('sm')]: {
                                        minWidth: 0,
                                        mr: open ? 3 : 10,
                                        justifyContent: 'flexEnd',
                                        alignSelf: 'flexEnd',
                                        color: 'primary.dark',
                                    },


                                }}
                            >
                                <Icon sx={{
                                    color: 'primary.contrastText', // Change the icon color

                                }}>
                                    {!open ? "chevron_right" : "chevron_left"}
                                </Icon>
                            </ListItemIcon>
                            <ListItemText primary={!isPortrait ? "Money Manager" : ''} sx={{

                                [theme.breakpoints.up('sm')]: {
                                    opacity: 1,
                                },


                            }}/>

                        </ListItemButton>
                        {menuItems.map((item) => (
                            <ListItemButton key={item.name}

                                            selected={window.location.pathname.includes(item.path)}
                                            onClick={()=> {
                                                navigate('money-manager/'+item.path, { state: { auth: auth, language: language } })

                                                console.log(item.name)
                                            }}
                                            divider={true}
                                            sx={{


                                                '.MuiSvgIcon-root, .MuiListItemIcon-root': {
                                                    color: 'primary.light', // Icon color when selected
                                                },
                                                // Custom styles for the button
                                                backgroundColor: 'primary.dark', // Example: using the theme's primary color
                                                '&:hover': {
                                                    backgroundColor: 'primary.main', // Darker shade on hover
                                                },
                                                '.MuiListItemText-primary': {
                                                    color: 'primary.light',
                                                },

                                                '&.Mui-selected': {
                                                    '.MuiListItemText-primary': {
                                                        color: 'primary.dark', // Text color when selected
                                                    },

                                                    '.MuiSvgIcon-root, .MuiListItemIcon-root': {
                                                        color: 'primary.dark', // Icon color when selected
                                                    },
                                                    backgroundColor: 'primary.light', // Example: different color when selected
                                                    '&:hover': {
                                                        backgroundColor: 'primary.main', // Darker shade when selected and hovered
                                                    },
                                                },
                                                '&.MuiListItemButton-divider':{

                                                    borderBottomColor: 'primary.contrastText',
                                                },
                                                color: 'primary.contrastText', // Change the text color
                                            }}

                            >



                                <ListItemIcon
                                    sx={{

                                        minWidth: 0,
                                        mr: open ? 3 : 'auto',
                                        justifyContent: 'center',
                                    }}
                                >
                                    <Icon sx={{
                                        color: 'inherit', // Change the icon color

                                    }}>
                                        {item.icon}
                                    </Icon>
                                </ListItemIcon>
                                <ListItemText primary={item.name} sx={{ opacity: open || isPortrait ? 1 : 0, color: 'primary.contrastText'}} />

                            </ListItemButton>

                        ))}
                    </Box>
                </MyDrawer>

                <Box sx={{ flexGrow:1 }}>
                    {children}

                </Box>
            </Box>
        </ThemeProvider>

    )


}

export default MainMenu;

