import React, {useEffect, useState} from 'react';
import {Divider, Skeleton, Stack} from "@mui/material";
import Box from "@mui/material/Box";
import {LineChart} from "@mui/x-charts";
import StatChip from "../income-outcome/StatChip";
import {useTranslation} from "react-i18next";
import {fetchSeveral} from "../../services/mainService";
import {fetchIncomeData} from "../../services/incomeService";
import {fetchOutcomeData} from "../../services/outcomeService";
import outcome from "../../pages/outcome";
import LinearProgress from "@mui/material/LinearProgress";

const PreviousMonthsStats = ({auth, monthRange}) => {

    const { t, i18n } = useTranslation();

    const [dataset, setDataset] = useState([])
    const [stats, setStats] = useState([])

    const [isLoading, setIsLoading] = useState(false);

    const currentDate = new Date();

    const fetchDataset = async () => {
        setIsLoading(true)
        const previousIncome = await fetchSeveral(auth, fetchIncomeData, currentDate, monthRange);
        const previousOutcome = await fetchSeveral(auth, fetchOutcomeData, currentDate, monthRange);

        const dataset = previousIncome.map(income => {
            const outcome = previousOutcome.find(outcome => outcome.month === income.month)
            const profit = income.price - outcome.price;
            return({
                month: income.month,
                profit: profit
            })
        })


        const totalProfit = {
            name: "Total Profit",
            tag: 'Total',
            icon: 'functions',
            color: 'primary',
            value: dataset.reduce((sum, entry) => sum + entry.profit, 0)
        };


        const averageProfit = {
            name: 'Average Profit',
            tag: 'Average',
            icon: 'attach_money',
            color: 'primary',
            value: totalProfit.value / dataset.length
        };
        setStats([ totalProfit, averageProfit])

        setDataset(dataset)

        setIsLoading(false)
    }

    useEffect(()=>{
        fetchDataset().then();
    }, [monthRange])

    return (
        <Box width={'100%'}>
            <Stack sx={{spacing: 1, alignItems:'center'}}>

                {isLoading && stats.length === 0 ? <>
                    <Skeleton variant="text" sx={{fontSize: '2rem', width: '60%'}}/>
                    <Skeleton variant="text" sx={{fontSize: '2rem', width: '60%'}}/>
                </> : stats.map(item => {
                    return (
                        <StatChip item={item}/>
                    )
                })

                }
            </Stack>
            {isLoading ? <LinearProgress/> : <Divider/>}
            <Box width={"100%"}>


                {isLoading && dataset.length === 0 ? <>
                        <Skeleton

                            variant="rectangular"

                            height={390}
                        />
                </> :
                    <LineChart
                        dataset={dataset}
                        series={[
                            {dataKey: "profit", label: t("Profit")},

                        ]}
                        xAxis={[{ dataKey: 'month', scaleType: 'band' }]}
                        margin={{ top: 60, bottom: 30, left: 70, right: 0 }}
                        height={390}

                    />
                }


            </Box>
        </Box>
    );
};

export default PreviousMonthsStats;