import React, {useEffect, useState} from 'react';
import {CircularProgress, Skeleton, Typography} from "@mui/material";
import {formatMoney} from "../../util";
import Box from "@mui/material/Box";
import {PieChart} from "@mui/x-charts";
import {t} from "i18next";
import {fetchIncomeData} from "../../services/incomeService";
import {fetchOutcomeData} from "../../services/outcomeService";
import {fetchCome} from "../../services/mainService";

const ThisMonthStats = ({auth}) => {
    const [balance, setBalance] = useState(0);
    const [outcome, setOutcome] = useState(0);
    const [isLoading, setIsLoading] = useState(false)

    const currentDate = new Date();
    const fetchMonth = async () => {

        const income = await fetchCome(fetchIncomeData, auth, currentDate.getMonth() + 1, currentDate.getFullYear(), setIsLoading)
        const outcome = await fetchCome(fetchOutcomeData, auth, currentDate.getMonth() + 1, currentDate.getFullYear(), setIsLoading)

        setOutcome(outcome.total)
        setBalance(income.total - outcome.total)
    }

    useEffect(()=>{
        fetchMonth().then()
    },[])
    return (
        <Box sx={{display: 'flex', flexDirection:'column', alignItems:'center'}}>
            <Typography variant={'h4'} component={'h4'}>{t("This Month")}</Typography>

            { isLoading ? <Skeleton variant="text" sx={{ fontSize: '1rem', width: '60%' }} /> :
                <Typography variant={'body1'}>
                    {formatMoney(balance)}
                </Typography>
            }



            <Box >

                {isLoading ? <Skeleton variant="circular" width={200} height={200} />:
                    <PieChart
                        slotProps={{
                            legend: { hidden: false },
                        }}
                        series={[
                            {
                                highlightScope: { faded: 'global', highlighted: 'item' },
                                faded: { innerRadius: 15, additionalRadius: -15, color: 'gray' },
                                data: [
                                    { id: 0, value: balance, label: t("Profit") },
                                    { id: 1, value: outcome, label: t("Expenses"), color: "#b50000"},

                                ],
                            },
                        ]}
                        width={400}
                        height={200}

                    />
                }

            </Box>
        </Box>
    );
};

export default ThisMonthStats;