import React, {useState} from 'react';
import {
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    Fab,
    Grid,
    Icon,
    Input,
    Slider,
    Typography
} from "@mui/material";
import Box from "@mui/material/Box";
import {t} from "i18next";
import OnlineChecker from "../../components/shared/OnlineChecker";
import TextField from "@mui/material/TextField";
import PriceFormat from "../../components/shared/PriceFormat";
import PercentageFormat from "../../components/shared/PercentageFormat";
import {VolumeUp} from "@mui/icons-material";
import Alert from "@mui/material/Alert";
import {API_URL, formatMoney} from "../../util";

const NewGoal = ({limit, auth, refreshData, disposableIncome}) => {

    const [isOpen, setOpen] = useState(false);

    const [nameInput, setNameInput] = useState('')
    const [percentageInput, setPercentageInput] = useState();
    const [msg, setMsg] = useState('');
    const marks = Array.from({ length: Math.round(limit*100) + 1}, (_, i) => ({
        value: i
    }));




    const onSaveNewGoal = ()=>{

        if (!percentageInput){
            setMsg(t('Please add a percentage'))
        } else {

            const body = {
                name: nameInput ? nameInput : t('New Saving Goal'),
                value: percentageInput/100,
            }

            fetch(`${API_URL}/saving-goals`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Accept': '*/*',
                    'Authorization': auth,
                },
                body: JSON.stringify(body)
            })
                .then(res=>{
                    if(!res.ok){
                        console.error('Network response was not ok', res);
                        setMsg('Network response was not ok');
                    } else {
                        setMsg('Successful');

                        refreshData()




                    }
                    return res.json()
                })
                .then(jsonD =>{
                        if (jsonD.offline){
                            setMsg(t('Saved Offline'))
                        }

                    }

                ).catch(err => {
                console.error(err);
                setMsg('Something went wrong');
            });
        }


    }
    return (
        <Box>
            <Fab disabled={limit<=0} variant="extended" color="primary" aria-label="add" onClick={()=>setOpen(true)}>
                <Icon>add</Icon>
                {t(`New Saving Goal`)}
            </Fab>

            <Dialog open={isOpen} onClose={()=>setOpen(false)} >
                <DialogTitle id="quick-input-title">
                    <Box display={'flex'} alignItems={'center'} >
                        <Icon onClick={()=>setOpen(false)} style={{cursor: "pointer", marginRight: "8%"}}  >
                            arrow_back
                        </Icon>


                        <Typography variant={'h4'} >
                            {t(`New Saving Goal`)}
                        </Typography>
                    </Box>


                </DialogTitle>

                <Box
                    component="form"
                    sx={{
                        '& .MuiTextField-root': { m: 1, width: '25ch' },
                        'display': 'flex',
                        'flexDirection':'column'
                    }}
                    noValidate

                    onSubmit={e=>{
                        e.preventDefault();
                        onSaveNewGoal();
                    }}
                >
                    <DialogContent sx={{
                        '& .MuiTextField-root': { m: 1, width: '25ch' },
                        display: 'flex',
                        flexDirection:'column',
                        alignItems: 'center'
                    }}>
                        <OnlineChecker/>
                        <Box sx={{minHeight:'50px', marginTop:'-8%'}}>
                            {msg ? <Alert severity={msg.includes('Successful') ? "success" : "error"}>{t(msg)}</Alert> : <></>}
                        </Box>
                        <TextField id="name"
                                   type="text"
                                   required
                                   error={!nameInput}
                                   label={t(`Name`)}
                                   variant="outlined"
                                   value={nameInput}
                                   onChange={(e) => setNameInput(e.target.value)}


                        />


                        <TextField
                            label={t("Percentage")}
                            value={percentageInput}
                            required
                            onChange={(e) => {
                                setPercentageInput(Number(e.target.value))

                            }}



                            InputProps={{
                                inputComponent: PercentageFormat,
                                type: 'text', // This needs to be text because we are using a custom number format
                                inputProps: {
                                    min: 0,
                                    max: Math.round(limit*100),

                                }
                            }}
                        />
                        <Box sx={{
                            width: '70%'
                        }}>
                            <Slider
                                value={typeof percentageInput === 'number' ? percentageInput : 0}
                                step={null}
                                marks={marks}
                                onChange={(e, newValue) => {
                                    setPercentageInput(newValue)
                                }}
                                aria-labelledby="input-slider"
                            />
                        </Box>
                        <Typography>
                            {formatMoney(disposableIncome*(percentageInput/100))}
                        </Typography>

                    </DialogContent>

                    <DialogActions>


                        <Button
                            variant="contained"
                            type={'submit'}
                            startIcon={<Icon>save</Icon>}
                        >
                            {t('Save')}

                        </Button>

                    </DialogActions>
                </Box>

            </Dialog>
        </Box>
    );
};

export default NewGoal;