import React, {useState} from 'react';
import { TableBody, TableCell, TableContainer, TableHead, TableRow, Typography} from "@mui/material";
import {t} from "i18next";

import Box from "@mui/material/Box";
import SavingRow from "./SavingRow";


const SavingsTable = ({docs, disposableIncome, isLoading, limit, refreshData, auth}) => {
    if(isLoading){
        return (
            <></>
        )
    }
    if (!docs){
        return (
            <Box sx={{
                width: '80%',
            }}>
                <Typography>
                    {t('No savings created yet. Start setting your savings goals now to achieve your financial objectives!')}
                </Typography>
            </Box>

        )
    }
    if (disposableIncome<=0){
        return (
            <Box sx={{
                width: '80%',
            }}>
                <Typography>
                    {t('Your disposable income is currently negative. Consider reviewing your expenses and budget to find areas where you can cut costs and improve your financial situation.')}
                </Typography>
            </Box>

        )
    }
    return (
        <Box sx={{
            margin: '2% 0 2% 0'
        }}>
            <TableContainer>
                <TableHead sx={{
                    backgroundColor: theme => theme.palette.primary.main,
                    color: theme => theme.palette.primary.light,
                }}>
                    <TableRow>

                        {['Name', 'Percentage', 'Price'].map((head)=>{
                            return(
                                <TableCell sx={{ color: theme => theme.palette.primary.contrastText }}>{t(head)}</TableCell>
                            )
                        })}

                    </TableRow>
                </TableHead>
                <TableBody>
                    {docs?.map(saving => {
                        return(
                            <SavingRow saving={saving}
                                       disposableIncome={disposableIncome}
                                       limit={limit} refreshData={refreshData} auth={auth}/>
                            )

                    })}
                </TableBody>

            </TableContainer>
        </Box>

    );
};

export default SavingsTable;