import React from 'react';
import {calculateTotal, formatMoney} from "../../../util";
import {TableCell, TableRow} from "@mui/material";

const TotalRow = ({type, docs, selectedCategory}) => {
    let array = ['Total',]
    if(type?.includes('frequent')){

        let total = docs ? formatMoney(docs.reduce((acc, item) => {
                if (selectedCategory !== '' && selectedCategory === item.category) {
                    return acc + item.price / item.frequency;
                } else if (selectedCategory === '') {
                    return acc + item.price / item.frequency;
                } else {
                    return acc; //
                }
            }
            , 0)) : null
        array.push('', '', total);

    } else{
        const total = formatMoney(calculateTotal(docs, 'price'))
        array.push('', total, '');


    }
    return(
        <TableRow sx={{

            backgroundColor: theme => theme.palette.primary.main,
        }}>
            {array?.map((element, index)=>{
                return(
                    <TableCell key={index} sx={{ color: theme => theme.palette.primary.contrastText }}>

                        {element}

                    </TableCell>
                )
            })}
        </TableRow>
    )
};

export default TotalRow;