import React, {useState} from 'react';
import {
    Button,
    Dialog,
    DialogActions,
    DialogContent, DialogTitle,
    Icon,
    Slider,
    TableCell,
    TableRow,
    Typography
} from "@mui/material";
import {API_URL, formatMoney} from "../../util";
import Box from "@mui/material/Box";
import {t} from "i18next";
import OnlineChecker from "../../components/shared/OnlineChecker";
import Alert from "@mui/material/Alert";
import TextField from "@mui/material/TextField";
import PercentageFormat from "../../components/shared/PercentageFormat";

const SavingRow = ({auth, saving, disposableIncome, limit: totalLimit, refreshData}) => {


    const limit = totalLimit + saving.value
    const [open, setOpen] = useState(false);

    const [nameInput, setNameInput] = useState(saving.name)
    const [percentageInput, setPercentageInput] = useState(saving.value*100);
    const [msg, setMsg] = useState('');
    const marks = Array.from({ length: Math.round(limit*100) + 1}, (_, i) => ({
        value: i
    }));


    const onDeleteGoal = () => {
        const confirmed = window.confirm(t('Are you sure you want to delete this item?'));
        if (confirmed){
            fetch(`${API_URL}/saving-goals/${saving._id}`,{
                method: 'DELETE',
                headers: {
                    'Content-Type': 'application/json',
                    'Accept': '*/*',
                    'Authorization': auth,
                },
            })
                .then(res=>{
                    return(res.json())
                })
                .finally(()=>{
                    setOpen(false)
                    refreshData()
                })
        }

    }
    const onSaveGoal = () =>{

        if (!percentageInput || percentageInput < 0){
            setMsg('Please add a percentage')
        } else {
            const body = [
                {propName: 'name', value: nameInput ? nameInput : t('New Saving Goal')},
                {propName: 'value', value: percentageInput/100},

            ]

            fetch(`${API_URL}/saving-goals/${saving._id}`, {
                method: 'PATCH',
                headers: {
                    'Content-Type': 'application/json',
                    'Accept': '*/*',
                    'Authorization': auth,
                },
                body: JSON.stringify(body)
            })
                .then(res=>{
                    if(!res.ok){
                        console.error('Network response was not ok', res);
                        setMsg('Network response was not ok');
                    } else {
                        setMsg('Successful');

                        refreshData()




                    }
                    return res.json()
                })
                .then(jsonD =>{
                        if (jsonD.offline){
                            setMsg(t('Saved Offline'))
                        }

                    }

                ).catch(err => {
                    console.error(err);
                    setMsg('Something went wrong');
                })
                .finally(()=>{
                    setOpen(false)
                })
        }
    }
    return(
        <>
            <TableRow key={saving.name} onClick={()=>setOpen(true)} sx={{
                cursor: 'pointer',

            }}>
                <TableCell>
                    {saving.name}
                </TableCell>
                <TableCell align="right">
                    {saving.value*100}%
                </TableCell>
                <TableCell  align="right">
                    {formatMoney(saving.value*disposableIncome)}
                </TableCell>
            </TableRow>

            <Dialog open={open} onClose={()=>setOpen(false)}>
                <DialogTitle id="quick-input-title">
                    <Box display={'flex'} alignItems={'center'} >
                        <Icon onClick={()=>setOpen(false)} style={{cursor: "pointer", marginRight: "8%"}}  >
                            arrow_back
                        </Icon>


                    <Typography variant={'h4'} >
                        {t(`Editing Saving Goal`)}
                    </Typography>
                </Box>


            </DialogTitle>

            <Box
                component="form"
                sx={{
                    '& .MuiTextField-root': { m: 1, width: '25ch' },
                    'display': 'flex',
                    'flexDirection':'column'
                }}
                noValidate

                onSubmit={e=>{
                    e.preventDefault();
                    onSaveGoal();
                }}
            >
                <DialogContent sx={{
                    '& .MuiTextField-root': { m: 1, width: '25ch' },
                    display: 'flex',
                    flexDirection:'column',
                    alignItems: 'center'
                }}>
                    <OnlineChecker/>
                    <Box sx={{minHeight:'50px', marginTop:'-8%'}}>
                        {msg ? <Alert severity={msg.includes('Successful') ? "success" : "error"}>{t(msg)}</Alert> : <></>}
                    </Box>
                    <TextField id="name"
                               type="text"
                               required
                               error={!nameInput}
                               label={t(`Name`)}
                               variant="outlined"
                               value={nameInput}
                               onChange={(e) => setNameInput(e.target.value)}


                    />


                    <TextField
                        label={t("Percentage")}
                        value={percentageInput}
                        required
                        onChange={(e) => {
                            setPercentageInput(Number(e.target.value))

                        }}



                        InputProps={{
                            inputComponent: PercentageFormat,
                            type: 'text', // This needs to be text because we are using a custom number format
                            inputProps: {
                                min: 0,
                                max: Math.round(limit*100),

                            }
                        }}
                    />
                    <Box sx={{
                        width: '70%'
                    }}>
                        <Slider
                            value={typeof percentageInput === 'number' ? percentageInput : 0}
                            step={null}
                            marks={marks}
                            onChange={(e, newValue) => {
                                setPercentageInput(newValue)
                            }}
                            aria-labelledby="input-slider"
                        />
                    </Box>
                    <Typography>
                        {formatMoney(disposableIncome*(percentageInput/100))}
                    </Typography>

                </DialogContent>

                <DialogActions>
                    <Button onClick={onDeleteGoal}
                            startIcon={<Icon>delete</Icon>}
                    >️
                        {t("Delete")}
                    </Button>

                    <Button
                        variant="contained"
                        type={'submit'}
                        startIcon={<Icon>save</Icon>}
                    >
                        {t('Save')}

                    </Button>

                </DialogActions>
            </Box>
            </Dialog>
        </>

    )
};

export default SavingRow;