import React from 'react';
import {Avatar, Skeleton, Stack, Typography} from "@mui/material";
import {theme} from "../../config/ThemeMUI";
import Box from "@mui/material/Box";
import {useNavigate} from "react-router-dom";
import {useTranslation} from "react-i18next";

const Header = ({user, auth, language}) => {
    const { t, i18n } = useTranslation();

    const navigate = useNavigate();

    return (
        <Box id={'header'} display="flex" alignItems="center" justifyContent="space-between" sx={{width: '100%'}} >
            <Stack
                sx={{flex: 1, cursor: "pointer",  alignItems: 'center',}} onClick={()=>{
                navigate('/money-manager/home/user', { state: {
                        auth:auth,
                        language: language,
                        id: user._id,
                        name: user.name,
                        email: user.email
                    }} )
            }}>
                <Avatar sx={{bgcolor:  theme.palette.primary.dark}}>
                    {user.name ? user.name[0] : null}
                </Avatar>

                {
                    !user.name ?
                        <>
                            <Skeleton variant="text" sx={{fontSize: '1rem', width: '60%'}}/>
                        </>
                        :
                        <Typography style={{margin:0}}>
                        {user.name}
                    </Typography>
                }
            </Stack>

            <Box sx={{flex: 2,  textAlign: 'center', marginLeft: '-21%'}}>
                <Typography variant={'h1'} component={'h1'} >{t("Home")}</Typography>
            </Box>

        </Box>
    );
};

export default Header;