import React, {useState} from 'react';
import {Button, Dialog, DialogActions, DialogContent, DialogTitle, Icon, Typography} from "@mui/material";
import Box from "@mui/material/Box";
import {t} from "i18next";
import OnlineChecker from "../OnlineChecker";
import Alert from "@mui/material/Alert";
import TextField from "@mui/material/TextField";
import FrequencySelector from "../../income-outcome/FrequencySelector";
import {LocalizationProvider} from "@mui/x-date-pickers/LocalizationProvider";
import {AdapterDayjs} from "@mui/x-date-pickers/AdapterDayjs";
import {DatePicker} from "@mui/x-date-pickers/DatePicker";
import dayjs from "dayjs";
import PriceFormat from "../PriceFormat";
import Autocomplete from "@mui/material/Autocomplete";
import {API_URL, daysToMonths, monthToFormat, weeksToMonths, yearsToMonths} from "../../../util";

const MainEditDialog = ({open, setOpen, type, item, auth, id, categories, refresh}) => {
    const isFrequent = type?.includes('frequent');


    const [nameInput, setNameInput] = useState(item.name);
    const [priceInput, setPriceInput] = useState(item.price);
    const [categoryInput, setCategoryInput] = useState(item.category);
    const [msg, setMsg] = useState('');

    const [selectedDate, setSelectedDate] = useState(dayjs(item.date));

    const [frequencyInput, setFrequencyInput] = useState(()=>{
        return monthToFormat(item.frequency)[0]
    });
    const [frequencyScale, setFrequencyScale] = useState(()=>{

        return monthToFormat(item.frequency)[2]
    });

    const [isLoading, setIsLoading] = useState(true);

    const changeFrequencyInput = (newInput) => {
        setFrequencyInput(newInput);
    }
    const changeFrequencyScale = (newFrequency) =>{
        setFrequencyScale(newFrequency);
    }


    const onSave = () => {

        const newData = [
            {
                "propName": "name",
                "value": nameInput
            },
            {
                "propName": "price",
                "value": priceInput
            },

            {
                "propName": "category",
                "value": categoryInput
            },
        ]
        if (isFrequent){

            let frequencyMonth;

            if(frequencyScale?.includes('dd')){


                frequencyMonth = (daysToMonths(frequencyInput));

            } else if(frequencyScale?.includes('ww')){


                frequencyMonth = (weeksToMonths(frequencyInput));

            } else if (frequencyScale?.includes('yy')){

                frequencyMonth = (yearsToMonths(frequencyInput));

            } else if (frequencyScale?.includes('mm')){

                frequencyMonth = (frequencyInput);

            }

            newData.push({
                "propName": "frequency",
                "value": frequencyMonth ? frequencyMonth : 1
            })
        }else {

            newData.push({
                "propName": "date",
                "value": selectedDate
            })
        }



        fetch(`${API_URL}/${type}/${id}`, {
            method: 'PATCH',
            headers: {
                'Content-Type': 'application/json',
                'Accept': '*/*',
                'Authorization': auth,
            },
            body: JSON.stringify(newData)
        }).then(res=> {
            if (res.ok){
                setMsg('Successful')
                alert(t('Changes saved successfully'));

            }
            else {
                setMsg('Something went wrong')
            }
        })
            .finally(()=>{
                const currentDate = new Date()
                setOpen(false);

                refresh(currentDate.getMonth() + 1, currentDate.getFullYear() )
            })

    }
    const onDelete = ()=>{
        const confirmed = window.confirm(t('Are you sure you want to delete this item?'));

        console.log(`${API_URL}/${type}/${id}`)
        if (confirmed){
            fetch(`${API_URL}/${type}/${id}`,{
                method: 'DELETE',
                headers: {
                    'Content-Type': 'application/json',
                    'Accept': '*/*',
                    'Authorization': auth,
                },
            }).then(res=>{
                return(res.json())
            })
                .then(d => console.log(d))
                .finally(()=>{
                    setOpen(false)

                })
        }


    }

    return (
        <Dialog open={open} onClose={()=>setOpen(false)} >
            <DialogTitle >

                <Box display={'flex'} alignItems={'center'} >
                    <Icon onClick={()=>setOpen(false)} style={{
                        cursor: "pointer",
                        marginRight: "8%"
                    }}  >
                        arrow_back
                    </Icon>


                    <Typography variant={'h4'} >
                        {t("Editing")}
                    </Typography>
                </Box>


            </DialogTitle >

            <Box
                component="form"
                sx={{
                    '& .MuiTextField-root': { m: 1, width: '25ch' },
                    'display': 'flex',
                    'flexDirection':'column'
                }}
                noValidate

                onSubmit={e=>{
                    e.preventDefault();
                    onSave();
                }}
            >

                <DialogContent sx={{
                    '& .MuiTextField-root': { m: 1, width: '25ch' },
                    'display': 'flex',
                    'flexDirection':'column'
                }}>



                    <OnlineChecker/>

                    {msg ? <Alert severity={msg?.includes('successful') ? "success" : "error"}>{t(msg)}</Alert> : null}


                    <Box
                        component="form"
                        sx={{
                            '& .MuiTextField-root': {m: 1, width: '25ch'},
                            'display': 'flex',
                            'flexDirection': 'column'
                        }}
                        noValidate
                        autoComplete="off"
                    >
                        <TextField id="name"
                                   type="text"
                                   error={!nameInput}
                                   label={t("Name")}
                                   variant="outlined"
                                   value={nameInput}
                                   onChange={(e) => setNameInput(e.target.value)}

                        />
                        {isFrequent ?
                            <FrequencySelector frequencyScale={frequencyScale} frequencyInput={frequencyInput}
                                               changeFrequencyScale={changeFrequencyScale}
                                               changeFrequencyInput={changeFrequencyInput}/> :
                            <LocalizationProvider dateAdapter={AdapterDayjs}>
                                <DatePicker label={t('Date')}
                                            value={selectedDate}
                                            views={['day', 'month']}

                                            onChange={(newValue) => setSelectedDate(dayjs(newValue))} />
                            </LocalizationProvider>}

                        <TextField id="price"

                                   label={t("Price")}
                                   variant="outlined"
                                   value={priceInput}
                                   error={!priceInput}
                                   onChange={(e) => setPriceInput(e.target.value)}
                                   InputProps={{
                                       inputComponent: PriceFormat,
                                   }}

                        />

                        <Autocomplete
                            freeSolo
                            disablePortal
                            id="category"
                            options={categories}
                            value={categoryInput}

                            onChange={(e, newValue) => setCategoryInput(newValue)}
                            renderInput={(params) =>
                                <TextField onChange={(e) => setCategoryInput(e.target.value)} {...params}
                                           label="Category" error={!categoryInput}/>}
                        />
                    </Box>






                </DialogContent>

                <DialogActions>


                    <Button onClick={onDelete}
                            startIcon={<Icon>delete</Icon>}
                    >️
                        {t("Delete")}
                    </Button>

                    <Button
                        type={'submit'}
                        variant={"contained"}
                        startIcon={<Icon>save</Icon>}
                    >
                        {t("Save")}
                    </Button>


                </DialogActions>
            </Box>

        </Dialog>
    );
};

export default MainEditDialog;