import {formatMoney, monthToFormat} from "../../../util";
import React, { useState} from "react";
import {useTranslation} from "react-i18next";
import dayjs from "dayjs";
import EditModule from "../../../pages/edit";
import {

    TableBody,
    TableCell, TableContainer, TableHead,
    TableRow,useTheme
} from "@mui/material";
import MainRow from "./MainRow";
import TableHeader from "./TableHeader";
import TotalRow from "./TotalRow";
import {TableContainerSx} from "./TableStylesSx";
import Box from "@mui/material/Box";





const MainTable = ({   auth,language,selectedCategory,headers,docs,type,categories,refresh})=>{
    const {t} = useTranslation();




    return (

            <TableContainer sx={TableContainerSx}>

                <TableHeader headers={headers}/>

                <TableBody>
                    {docs ? docs.map((item, index) => {
                        let array = [];
                        if(item.date){
                            array.push(dayjs(item.date).date())
                        }
                        else {
                            array.push(index+1)
                        }

                        if(item.name){
                            array.push(item.name)
                        }
                        if(item.frequency){
                            let freq = monthToFormat(item.frequency)
                            let freqPrice = formatMoney(item.price);

                            if(freq[0] === 1 && freq[1].includes('Month')){
                                array.push('')
                                array.push(`${formatMoney(item.price/item.frequency)}`)
                            }else   {
                                array.push(`${freqPrice} ${t('every')} ${freq[0] > 1 ? freq[0] : ''} ${t(freq[1])}`)
                                array.push(`${formatMoney(item.price/item.frequency)}`)
                            }



                        } else  {
                            if (item.price){
                                array.push(formatMoney(item.price))
                            }
                            if (item.category){
                                array.push(item.category)
                            }
                        }


                        if (selectedCategory === '' || item.category === selectedCategory) {

                            return <MainRow elements={array}
                                            id={item._id}
                                            key={item._id}
                                            auth={auth}
                                            type={type}
                                            language={language}
                                            categories={categories}
                                            doc={item}
                                            refresh={refresh}
                                            item={item}
                            />
                        } else {
                            return <></>
                        }

                    }) : <></>}

                    <TotalRow type={type} docs={docs} selectedCategory={selectedCategory}/>

                </TableBody>



            </TableContainer>


    )
}

export default MainTable;