import React from 'react';
import {
    CircularProgress,
    Stack,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    Typography
} from "@mui/material";
import MainTable from "../../components/shared/MainTable/MainTable";
import {useTranslation} from "react-i18next";
import {categoryTableStackSx} from "../SxStyles";
import {t} from "i18next";

const CategoryTables = ({monthlyDocs, frequentCats, fetchFrequents, language, isLoading, auth}) => {
    const {t, i18n} = useTranslation();
    if (isLoading){
        return (
            <CircularProgress/>
        )
    }
    return (
        <Stack sx={{alignItems: "center", width: "100%"}}>
            {monthlyDocs ? monthlyDocs.map((cat) => {
                return (
                    <Stack sx={categoryTableStackSx} key={cat.category}>
                        <Typography variant={'h4'}>{t('Category')} {cat.category}</Typography>



                        <MainTable auth={auth} categories={frequentCats} selectedCategory={cat.category}
                                   type={'frequent-outcomes'} docs={cat.elements[0]} language={language}
                                   headers={['#', t('Expenses'), t('Frequency'), t('Monthly Budget')]}
                                   refresh={fetchFrequents}/>
                    </Stack>


                )
            }) : null}
        </Stack>
    );
};

export default CategoryTables;