import React, {useEffect, useState} from 'react';
import {ThemeProvider} from "@mui/material/styles";
import {theme, themeRed} from "../../config/ThemeMUI";
import {Button, CircularProgress, Container, Icon, Stack, Typography} from "@mui/material";
import {calculateAverage, calculateTotal, formatMoney} from "../../util";
import QuickInput from "../../components/income-outcome/quickInput";
import {t} from "i18next";
import {useLocation, useNavigate} from "react-router-dom";
import {linearProgressBoxSx, mainStackSx} from "../../config/SxStyles";
import TextField from "@mui/material/TextField";
import Header from "../shared/Header";
import {fetchSavingData} from "../../services/savingService";
import {fetchIncomeData} from "../../services/incomeService";
import {fetchFrequentData} from "../../services/frequentService";
import PriceFormat from "../../components/shared/PriceFormat";
import LinearProgress from "@mui/material/LinearProgress";
import Box from "@mui/material/Box";
import InputField from "./InputField";
import NewGoal from "./NewGoal";
import SavingsTable from "./SavingsTable";
import {fetchSeveral} from "../../services/mainService";
import {fetchOutcomeData} from "../../services/outcomeService";

const Savings = () => {
    const location = useLocation();
    const auth = location.state?.auth;
    const language = location.state?.language;


    const currentDate = new Date()

    const [income, setIncome] = useState(0);
    const [budget, setBudget] = useState(0);

    const [isLoading, setIsLoading] = useState(true);

    const [savingsDocs, setSavingsDocs] = useState([])

    const [defaultBudget, setDefaultBudget] = useState([]);
    const [defaultIncome, setDefaultIncome] = useState([]);
    const [newGoalLimit, setGoalLimit] = useState(0);



    const previousMonths = ()=>{
        // Get data from localStorage if it exists
        const savedNumber = localStorage.getItem('previousMonths');
        return savedNumber ? JSON.parse(savedNumber) : 3;
    }
    const fetchKnownData = async () => {

        setIsLoading(true)

        const frequent = await fetchFrequentData(auth);


        const pastIncome = await fetchSeveral(auth, fetchIncomeData, currentDate, previousMonths())

        const pastExpenses = await fetchSeveral(auth, fetchOutcomeData, currentDate, previousMonths());

        const averageExpenses = (calculateAverage(pastExpenses, 'price'))
        const totalFrequent = calculateTotal(frequent.docs, 'price')



        const defaultBudget = [
            {
                name: t('This Month'),
                value: pastExpenses[0].price,
                help: t('The sum of all your expenses for the month')

            },
            {
                name: t('Smart'),
                value: Math.round((averageExpenses * 0.6) + (totalFrequent * 0.4)),
                help: t('Combines your average monthly expenses with your monthly budget to create a realistic budget')
            },
            {
                name: t('Monthly Budget'),
                value: totalFrequent,
                help: t('The total amount planned for your monthly expenses')
            },

        ];
        const defaultIncome = [
            {
                name: t('This Month'),
                value: pastIncome[0].price,
                help: t('The sum of all your income sources for the month')
            },
            {
                name: t('Average'),
                value: Math.round(calculateAverage(pastIncome, 'price')),
                help: t('The average of your monthly income over the past months')

            }
        ]

        setDefaultBudget(defaultBudget)
        setDefaultIncome(defaultIncome)


        setIsLoading(false)

    }


    const fetchSavings = async () => {
        const response = await fetchSavingData(auth);
        const sortedDocsAscending = response.docs.sort((a, b) => a.value - b.value)
        setSavingsDocs(sortedDocsAscending);
        const total = calculateTotal(response.docs, 'value')
        setGoalLimit(1-total)

    }

    useEffect(() => {
        fetchKnownData().then()
        fetchSavings().then()
    }, []);
    return (
        <ThemeProvider theme={theme}>
            <Stack   sx={mainStackSx}>

                <Header title={'Saving Goals'}/>

                <Box sx={linearProgressBoxSx}>
                    {isLoading ? <LinearProgress/> : <></>}
                </Box>




                <InputField name={'Income'}
                            value={income} setValue={setIncome}
                            help={'Enter the total amount from all your income sources'}
                            defaultValues={defaultIncome}
                            isLoading={isLoading}
                />


                <InputField name={'Budget'}
                            value={budget} setValue={setBudget}
                            help={'Specify the total amount planned for your expenses'}
                            defaultValues={defaultBudget}
                            isLoading={isLoading}
                />


                <Typography variant={'h3'}>{t('Disposable Income')}:</Typography>
                <Typography variant={'h4'} sx={{
                    margin: '2% 0 2% 0'
                }}>{formatMoney(income-budget)}</Typography>
                <NewGoal limit={newGoalLimit} auth={auth} refreshData={fetchSavings} disposableIncome={income-budget}/>
                <SavingsTable docs={savingsDocs} language={language} disposableIncome={income-budget} isLoading={isLoading}
                              limit={newGoalLimit} auth={auth} refreshData={fetchSavings}/>




            </Stack>
        </ThemeProvider>
    );
};

export default Savings;