import React, {useEffect} from 'react';
import {Button, Icon, InputAdornment, Skeleton, Stack, Tooltip, Typography} from "@mui/material";
import {t} from "i18next";
import TextField from "@mui/material/TextField";
import PriceFormat from "../../components/shared/PriceFormat";
import Box from "@mui/material/Box";
import {linearProgressBoxSx} from "../../config/SxStyles";
import LinearProgress from "@mui/material/LinearProgress";
import ButtonGroup from "@mui/material/ButtonGroup";

const InputField = ({name, value, setValue, help, defaultValues, isLoading}) => {

    useEffect(() => {
        if (defaultValues[0] && !isLoading){
            setValue(defaultValues[0].value)
        }
    }, [isLoading]);

    return (
        <Stack sx={{
            margin:'1rem 0 2rem 0',
            alignItems: 'center',
        }}>
            <Stack sx={{
                alignItems:'center',
                gap: 1,

            }}>
                <Typography variant={'h3'}>{t(name)}:</Typography>
                <Typography>
                    {t(help)}
                </Typography>
                <TextField variant="standard"
                           error={!value}
                           value={value}
                           onChange={event => setValue(event.target.value)}
                           InputProps={{
                               inputComponent: PriceFormat,
                           }}
                />
            </Stack>


            {isLoading ?
                <Skeleton variant="rounded" width={310} height={37} sx={{
                    margin: '2% 0 0 0',

                }}/> :
                <ButtonGroup sx={{
                    margin: '2% 0 0 0',

                }}>
                    {defaultValues?.map(defaultValue=>{
                        return(
                            <Tooltip title={defaultValue.help}>
                                <Button onClick={()=>setValue(defaultValue.value)} >
                                    {defaultValue.name}
                                </Button>
                            </Tooltip>

                        )
                    })}

                </ButtonGroup>
            }


        </Stack>
    );
};

export default InputField;