import React, {useState, useEffect, useContext} from "react";
import {Navigate, useLocation, useNavigate} from 'react-router-dom';

import {formatMoney, API_URL} from "../util";
import './styles.css';


import {useTranslation} from "react-i18next";
import {Avatar, Chip, CircularProgress, Divider, Icon, Slider, Stack, Tooltip, Typography} from "@mui/material";
import {ThemeProvider} from "@mui/material/styles";
import {theme} from "../config/ThemeMUI";
import { BarChart } from '@mui/x-charts/BarChart';
import Box from "@mui/material/Box";
import {LineChart, PieChart} from "@mui/x-charts";

import {MyContext} from "../App";
import MonthRangeSelector from "../components/shared/MonthRangeSelector";
import Header from "../components/home/header";
import ThisMonthStats from "../components/home/ThisMonthStats";
import {mainStackSx} from "../config/SxStyles";
import PreviousMonthsStats from "../components/home/PreviousMonthsStats";


const HomePage = () => {

    const { t, i18n } = useTranslation();

    // receives auth as a parameter when redirecting

    const location = useLocation();
    const language = location.state?.language;




    const {isAuth, updateIsAuth} = useContext(MyContext);

    const [auth] = useState(()=>{
        const savedToken = localStorage.getItem('token');
        updateIsAuth(true)
        return savedToken ? JSON.parse(savedToken) : '';
    })


    const [user] = useState("");








    const [monthRange, setMonthRange] = useState(()=>{
        // Get data from localStorage if it exists
        const savedNumber = localStorage.getItem('previousMonths');
        return savedNumber ? JSON.parse(savedNumber) : 3;
    })





    useEffect(()=>{

        localStorage.setItem('previousMonths', JSON.stringify(monthRange));

    },[monthRange])

    if (!isAuth) {
        return <Navigate to='/money-manager/login' />;
    }
    return (
        <ThemeProvider theme={theme}>
        <Stack sx={mainStackSx}>
            <Stack >



                <Header auth={auth} language={language} user={user}/>







                        <Stack marginBottom={'20%'} alignItems={'center'} >



                            <ThisMonthStats auth={auth} />



                            <MonthRangeSelector monthRange={monthRange} setMonthRange={setMonthRange}/>




                            <PreviousMonthsStats auth={auth} monthRange={monthRange} />


                        </Stack>







            </Stack>

        </Stack>
        </ThemeProvider>
        
    );
}
export default HomePage;
